  stmts := ARRAY_APPEND(:stmts,
    'COPY INTO @' || :tgt || '.APP_STAGE/source/2029ed3fb228a9bb/vite.config.ts FROM (SELECT BASE64_DECODE_STRING(''' || BASE64_ENCODE(BASE64_DECODE_STRING('aW1wb3J0IHsgZGVmaW5lQ29uZmlnIH0gZnJvbSAidml0ZSI7CmltcG9ydCByZWFjdCBmcm9tICJAdml0ZWpzL3BsdWdpbi1yZWFjdCI7CmltcG9ydCBwYXRo'
