  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''INTERACT_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''INTERACT_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''INTERACT_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''INTERACT_APP'' AND "comment"=''oneshot-source:16_interactive_analytics''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.INTERACT_APP FROM ''@__TARGET__.APP_STAGE/source/2029ed3fb228a9bb/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:16_interactive_analytics''; ALTER STREAMLIT __TARGET__.INTERACT_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
  stmts := ARRAY_APPEND(:stmts, REPLACE('BEGIN DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20071,''ONESHOT_SOURCE belongs to a different installation''); BEGIN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE''; IF (:present_count>0) THEN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE'' AND "comment"=''oneshot-source:16_interactive_analytics''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE WORKSPACE __TARGET__.ONESHOT_SOURCE COMMENT=''oneshot-source:16_interactive_analytics''; ALTER WORKSPACE __TARGET__.ONESHOT_SOURCE ADD LIVE VERSION FROM LAST; COPY FILES INTO ''snow://workspace/__TARGET__.ONESHOT_SOURCE/versions/live/'' FROM @__TARGET__.APP_STAGE/source/2029ed3fb228a9bb/; END IF; END; EXCEPTION WHEN OTHER THEN NULL; END', '__TARGET__', :tgt));
  notes := ARRAY_APPEND(:notes, 'Editable source: ' || :tgt || '.ONESHOT_SOURCE. Existing workspace and app source are preserved on rerun.');
  notes := ARRAY_APPEND(:notes, 'OPEN THE APP after building: Snowsight > Projects > Streamlit > INTERACT_APP');
  cost_day := :cost_day + 0.10;
